if (cmd === "LED ON" || cmd === "ON" || cmd === "1") {
  tx = "0\n";            // マイコン側で ON と解釈する値

} else if (cmd === "LED OFF" || cmd === "OFF" || cmd === "0") {
  tx = "x\n";            // OFF

}else if (cmd === "GPS" || cmd === "gps" ) {
  tx = "1\n";            // GPS

} else if (cmd === "状態問い合わせ" || cmd === "state" || cmd === "?") {
  tx = "s\n";            // 状態問い合わせ（使わないなら消してOK）

