  msg.isError = true;
  return msg;            // ここも次で返信/ログに回す
}

// マイコンへ送るテキストを payload に入れる
msg.payload = tx;

// デバッグしやすいように残す（任意）
msg.cmd = cmd;
msg.tx = tx;

return msg;

