  msg.gnss = {
    valid: false,          // ← 重要：位置が無効
    fix: false,
    sats: isNaN(sats) ? null : sats,
    status: "NO_FIX",
    message: `${latRaw}, ${lonRaw}`,
    raw: line,
    ts: Date.now()
  };

  return msg;
}

