// --- helpers ---
function toBuffer(payload) {
    // serial in が Buffer で来るのが理想
    if (Buffer.isBuffer(payload)) return payload;

    // 文字列なら「バイナリ」として扱う（設定ミス時の応急）
    if (typeof payload === "string") return Buffer.from(payload, "binary");

    // ArrayBuffer / Uint8Array 系
    if (payload && payload.buffer && payload.byteLength !== undefined) {
        return Buffer.from(payload);
    }

    // number array
    if (Array.isArray(payload)) return Buffer.from(payload);

    return Buffer.alloc(0);
}

function concat2(a, b) {
    if (!a || a.length === 0) return b;
    if (!b || b.length === 0) return a;

    // Buffer.concat が使えるならそれを使う
    if (Buffer.concat) return Buffer.concat([a, b]);

    // 互換：手動で結合
    const out = Buffer.alloc(a.length + b.length);
    a.copy(out, 0);
    b.copy(out, a.length);
    return out;
}

// buf内から 'SPJG' を探す（indexOfが無い環境向け）
function findSig(buf, sig) {
    // indexOfが使えるなら早い
    if (buf.indexOf) return buf.indexOf(sig);

    // 手動検索
    for (let i = 0; i <= buf.length - sig.length; i++) {
        let ok = true;
        for (let j = 0; j < sig.length; j++) {
            if (buf[i + j] !== sig[j]) { ok = false; break; }
        }
        if (ok) return i;
    }
    return -1;
}

// --- main ---
let buf = context.get('buf');
if (!Buffer.isBuffer(buf)) buf = Buffer.alloc(0);

// 今回入ってきた分を追記
const incoming = toBuffer(msg.payload);
buf = concat2(buf, incoming);

// "SPJG"
const SIG = Buffer.from([0x53, 0x50, 0x4A, 0x47]);

while (true) {
    const idx = findSig(buf, SIG);
    if (idx < 0) {
        // バッファ肥大化防止：末尾だけ残す
        if (buf.length > 1024 * 1024) buf = buf.slice(-1024);
        break;
    }

    // 署名より前のゴミを捨てる
    if (idx > 0) buf = buf.slice(idx);

    // "SPJG"(4) + size(4) が揃ってる？
    if (buf.length < 8) break;

    // size little-endian（readUInt32LEが無い環境も考慮して手動）
    const size = (buf[4]) | (buf[5] << 8) | (buf[6] << 16) | (buf[7] << 24);

    // 妥当性チェック
    if (size < 2000 || size > 2_000_000) {
        // 偽ヒット対策：1バイト進めて再探索
        buf = buf.slice(1);
        continue;
    }

    const frameLen = 8 + size;
    if (buf.length < frameLen) break;

    // JPEG部分
    const jpg = buf.slice(8, 8 + size);

    // 次フレームへ
    buf = buf.slice(frameLen);
    context.set('buf', buf);

    // ★ 表示用（旧dashboard向け DataURL）
    msg.payload = "data:image/jpeg;base64," + jpg.toString('base64');

    // ★ 保存・LINE送信用（Buffer）
    msg.jpg = jpg;

    // ★ 5秒に1回だけ流す
    const now = Date.now();
    const last = context.get('lastEmit') || 0;
    if (now - last < 5000) {
        context.set('buf', buf);
        return null;
    }
    context.set('lastEmit', now);


    return msg; // 1フレームだけ流す（連続で来る）
}

// まだ揃ってないのでバッファ保持して終了
context.set('buf', buf);
return null;

// レスポンスヘッダー
msg.headers = {
